def _draw_mkt_orderbook(self, max_y, max_x):
    """Draw order book depth."""
    chart_top = 2
    chart_bot = max_y - 5
    chart_h = chart_bot - chart_top
    if chart_h < 5:
        return

    mid_x = max_x // 2
    bids = self.mkt_bids
